/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// The infinitive.
    Infinitive,
    /// The non-past: present tense for imperfective verbs, future for perfective ones. (The imperfective future is `буду` + infinitive and is not a form of the verb.)
    NonPast(Person, Number),
    /// The past tense.
    Past(Agreement),
    /// The imperative.
    Imperative(Number),
    /// A participle's citation form (masculine nominative singular); decline it with `adjective`.
    Participle(Participle),
    /// A gerund (adverbial participle).
    Gerund(Tense),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        let cell = match self {
            Cell::Infinitive => cell::INFINITIVE,
            Cell::NonPast(Person::First, Number::Singular) => cell::NON_PAST_1_SG,
            Cell::NonPast(Person::First, Number::Plural) => cell::NON_PAST_1_PL,
            Cell::NonPast(Person::Second, Number::Singular) => cell::NON_PAST_2_SG,
            Cell::NonPast(Person::Second, Number::Plural) => cell::NON_PAST_2_PL,
            Cell::NonPast(Person::Third, Number::Singular) => cell::NON_PAST_3_SG,
            Cell::NonPast(Person::Third, Number::Plural) => cell::NON_PAST_3_PL,
            Cell::Past(Agreement::Masculine) => cell::PAST_M,
            Cell::Past(Agreement::Feminine) => cell::PAST_F,
            Cell::Past(Agreement::Neuter) => cell::PAST_N,
            Cell::Past(Agreement::Plural) => cell::PAST_PL,
            Cell::Imperative(Number::Singular) => cell::IMPERATIVE_SG,
            Cell::Imperative(Number::Plural) => cell::IMPERATIVE_PL,
            Cell::Participle(Participle::PresentActive) => cell::PARTICIPLE_PRES_ACT,
            Cell::Participle(Participle::PastActive) => cell::PARTICIPLE_PAST_ACT,
            Cell::Participle(Participle::PresentPassive) => cell::PARTICIPLE_PRES_PASS,
            Cell::Participle(Participle::PastPassive) => cell::PARTICIPLE_PAST_PASS,
            Cell::Gerund(Tense::Present) => cell::GERUND_PRES,
            Cell::Gerund(Tense::Past) => cell::GERUND_PAST,
        };
        cell as usize
    }
}

impl From<(Person, Number)> for Cell {
    fn from((person, number): (Person, Number)) -> Self {
        Cell::NonPast(person, number)
    }
}

impl From<Agreement> for Cell {
    fn from(agreement: Agreement) -> Self {
        Cell::Past(agreement)
    }
}

impl From<Number> for Cell {
    fn from(number: Number) -> Self {
        Cell::Imperative(number)
    }
}

impl From<Participle> for Cell {
    fn from(participle: Participle) -> Self {
        Cell::Participle(participle)
    }
}

impl From<Tense> for Cell {
    fn from(tense: Tense) -> Self {
        Cell::Gerund(tense)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    full: bool,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
            full: false,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its lemma is spelled with every mark the dictionary writes, so
    /// none is hidden (without this, a lemma typed without marks may be
    /// missing some, and its forms are less sure).
    #[must_use]
    pub fn spelled_in_full(mut self) -> Self {
        self.full = true;
        self
    }

    fn known(&self) -> Known<'_, u8> {
        Known {
            forms: &self.given,
            feature: None,
            full: self.full,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
